        "https://resource.logitechg.com/w_544%2Ch_466%2Car_7%3A6%2Cc_pad%2Cq_auto%2Cf_auto%2Cdpr_1.0/d_transparent.gif/content/dam/gaming/en/products/rs50-system-pdp/2026-update/rs50-system-front-angle-play-station-gallery-1.png"
